<?php get_header(); while(have_posts()):the_post(); $id=get_the_ID(); $cities=wp_get_post_terms($id,'bsktv_city',array('fields'=>'names')); $types=wp_get_post_terms($id,'bsktv_type',array('fields'=>'names')); $global_line=get_theme_mod('bsktv_line_url',''); $line_url=bsktv_meta('bsktv_line_url_override')?:$global_line; $status=bsktv_meta('bsktv_status')?:'active'; $verified=bsktv_meta('bsktv_verified')==='1'; $verified_at=bsktv_meta('bsktv_verified_at'); $status_labels=array('active'=>'營業中','pending'=>'資料待確認','paused'=>'暫停營業','closed'=>'已歇業'); $status_label=$status_labels[$status]??'店家資訊'; $city_names=is_array($cities)&&$cities?$cities:array('店家'); $type_names=is_array($types)&&$types?$types:array('商務KTV'); $safe_status=in_array($status,array('active','pending','paused','closed'),true)?$status:'pending'; ?>
<main class="single-page"><article>
<header class="store-hero-detail"><div class="store-hero-image"><?php if(has_post_thumbnail())the_post_thumbnail('full',array('fetchpriority'=>'high','decoding'=>'async'));else echo '<div class="store-card-placeholder">BSKTV</div>'; ?><div class="store-hero-overlay"></div></div><div class="container store-hero-content"><div class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">首頁</a><span>/</span><?php echo esc_html(implode('、',$city_names)); ?></div><div class="store-kicker"><?php echo esc_html(implode(' · ',$type_names)); ?></div><h1><?php the_title(); ?></h1><div class="store-status status-<?php echo esc_attr($safe_status); ?>"><?php echo esc_html($status_label); ?><?php if($verified): ?><span class="verified-badge">✓ 資料已確認</span><?php endif; ?></div><div class="hero-actions"><button class="btn btn-gold" type="button" data-favorite data-id="<?php echo esc_attr($id); ?>" aria-label="收藏 <?php echo esc_attr(get_the_title()); ?>">♡ 收藏店家</button><?php if($line_url): ?><a class="btn btn-light desktop-contact" data-line-contact data-id="<?php echo esc_attr($id); ?>" href="<?php echo esc_url($line_url); ?>" target="_blank" rel="noopener noreferrer">LINE</a><?php endif; ?></div></div></header>
<div class="container section"><div class="single-layout"><div class="article-main"><div class="article-meta"><span>更新於 <?php echo esc_html(get_the_modified_date()); ?></span><span><?php echo esc_html(bsktv_views($id)); ?> 次瀏覽</span><?php if($verified_at): ?><span>資料確認於 <?php echo esc_html($verified_at); ?></span><?php endif; ?></div><div class="article-content"><?php the_content(); ?></div><?php $gallery=bsktv_gallery_ids($id);if($gallery): ?><section class="store-gallery" aria-labelledby="gallery-title"><div class="section-head"><div><span class="eyebrow">GALLERY</span><h2 id="gallery-title">店家相簿</h2></div><span class="gallery-count"><?php echo esc_html(count($gallery)); ?> 張</span></div><div class="gallery-grid"><?php foreach($gallery as $index=>$image_id){$full=wp_get_attachment_image_url($image_id,'full');$thumb=wp_get_attachment_image_url($image_id,'large');if($full&&$thumb)echo '<button type="button" class="gallery-item" data-gallery-item="'.esc_url($full).'" data-gallery-index="'.esc_attr($index).'" aria-label="查看 '.esc_attr(get_the_title()).' 圖片 '.esc_attr($index+1).'">'.wp_get_attachment_image($image_id,'large',false,array('loading'=>'lazy','decoding'=>'async','alt'=>get_the_title().' 圖片 '.($index+1))).'</button>';} ?></div></section><?php endif; ?></div><aside class="store-info"><div class="info-sticky"><div class="info-title"><span class="eyebrow">STORE INFO</span><h2>店家資訊</h2></div><?php $fields=array('bsktv_address'=>'地址','bsktv_hours'=>'營業時間','bsktv_service_mode'=>'坐檯模式','bsktv_room_fee'=>'包廂費用','bsktv_host_fee'=>'少爺費用','bsktv_person_fee'=>'人頭費用','bsktv_girl_fee'=>'小姐費用','bsktv_head_fee'=>'幹部費用');$has_info=false;foreach($fields as $k=>$label){$v=bsktv_meta($k);if($v!==''){$has_info=true;echo '<div class="info-row"><span class="info-label">'.esc_html($label).'</span><span>'.esc_html($v).'</span></div>';}}if(!$has_info)echo '<div class="info-empty">店家資訊整理中</div>';if($line_url): ?><a class="btn btn-primary btn-full" data-line-contact data-id="<?php echo esc_attr($id); ?>" href="<?php echo esc_url($line_url); ?>" target="_blank" rel="noopener noreferrer">LINE</a><?php else: ?><span class="btn btn-primary btn-full" aria-disabled="true" style="opacity:.5;cursor:not-allowed">LINE</span><?php endif; ?></div></aside></div></div></article><?php get_template_part('template-parts/related'); ?><?php if($line_url): ?><div class="mobile-contact-bar"><div><strong>需要店家資訊？</strong><span>直接聯絡幹部</span></div><a class="btn btn-gold" data-line-contact data-id="<?php echo esc_attr($id); ?>" href="<?php echo esc_url($line_url); ?>" target="_blank" rel="noopener noreferrer">LINE</a></div><?php endif; ?></main><?php endwhile; get_footer(); ?>